import { useState } from 'react'
import type { Risk, Settings, T, User } from './data'

type Props = {
  t: T
    settings: Settings
      update: (patch: Partial<Settings>) => void
        user: User | null
          setUser: (u: User | null) => void
            card: string
              muted: string
              }

              export default function ProfileScreen({ t, settings, update, user, setUser, card, muted }: Props) {
                const [name, setName] = useState('')
                  const [email, setEmail] = useState('')

                    const btn = (active: boolean) =>
                        active
                              ? 'px-3 py-1 rounded-full text-sm bg-violet-600 text-white'
                                    : `px-3 py-1 rounded-full text-sm border border-zinc-600 ${muted}`

                                      const inputClass = 'w-full rounded-lg bg-zinc-800 px-3 py-2 text-sm text-white outline-none'

                                        return (
                                            <div className="mx-4 mt-6 space-y-4">
                                                  <div className={`rounded-2xl ${card} p-5`}>
                                                          <h2 className="text-base font-semibold">{t.account}</h2>
                                                                  {user ? (
                                                                            <div className="mt-3">
                                                                                        <p className="text-sm">
                                                                                                      {t.welcome}, <span className="font-semibold">{user.name}</span>
                                                                                                                  </p>
                                                                                                                              <p className={`text-xs ${muted}`}>{user.email}</p>
                                                                                                                                          <button onClick={() => setUser(null)} className="mt-3 text-sm text-red-400">
                                                                                                                                                        {t.logout}
                                                                                                                                                                    </button>
                                                                                                                                                                              </div>
                                                                                                                                                                                      ) : (
                                                                                                                                                                                                <div className="mt-3 space-y-2">
                                                                                                                                                                                                            <input
                                                                                                                                                                                                                          value={name}
                                                                                                                                                                                                                                        onChange={(e) => setName(e.target.value)}
                                                                                                                                                                                                                                                      placeholder={t.name}
                                                                                                                                                                                                                                                                    className={inputClass}
                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                          value={email}
                                                                                                                                                                                                                                                                                                                        onChange={(e) => setEmail(e.target.value)}
                                                                                                                                                                                                                                                                                                                                      placeholder={t.email}
                                                                                                                                                                                                                                                                                                                                                    className={inputClass}
                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                            <button
                                                                                                                                                                                                                                                                                                                                                                                          onClick={() => {
                                                                                                                                                                                                                                                                                                                                                                                                          if (name.trim()) setUser({ name: name.trim(), email: email.trim() })
                                                                                                                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                                                                                                                                      className="w-full rounded-lg bg-violet-600 py-2 text-sm text-white"
                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                {t.login}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className={`rounded-2xl ${card} p-5 space-y-4`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h2 className="text-base font-semibold">{t.settings}</h2>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className={`text-sm ${muted} mb-2`}>{t.theme}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button className={btn(settings.dark)} onClick={() => update({ dark: true })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {t.dark}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button className={btn(!settings.dark)} onClick={() => update({ dark: false })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {t.light}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className={`text-sm ${muted} mb-2`}>{t.language}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button className={btn(settings.lang === 'en')} onClick={() => update({ lang: 'en' })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  English
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button className={btn(settings.lang === 'hi')} onClick={() => update({ lang: 'hi' })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Hinglish
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex items-center justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="text-sm">{t.notifications}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button className={btn(settings.notif)} onClick={() => update({ notif: !settings.notif })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {settings.notif ? t.on : t.off}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className={`rounded-2xl ${card} p-5 space-y-3`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h2 className="text-base font-semibold">{t.risk}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex gap-2 flex-wrap">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {(['conservative', 'moderate', 'aggressive'] as Risk[]).map((r) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button key={r} className={btn(settings.risk === r)} onClick={() => update({ risk: r })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {t[r]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className={`text-sm ${muted} pt-2`}>{t.goal}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={settings.goal}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={(e) => update({ goal: e.target.value })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder={t.goalPlaceholder}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className={inputClass}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className={`rounded-2xl ${card} p-5`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h2 className="text-base font-semibold">{t.about}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className={`text-sm ${muted} mt-2`}>{t.aboutText}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-xs text-yellow-400 mt-3">{t.disclaimer}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }